/*
 * Findings `#/findings`: the document (DESIGN.md "Composition plan"). It opens on the
 * instrument parked at the cut-off, then the dated verdict stamp (concept B), the question
 * and the one-paragraph answer. The charts follow the drawing rule: point estimates as ticks,
 * intervals as brackets, the permutation band hatched. Every number comes from
 * content/findings.json, generated by model/f1battery_model/hypothesis_test.py.
 */
import findings from "../content/findings.json";
import notes from "../content/findings-notes.json";
import straightNames from "../content/straight-names.json";
import { Avatar } from "../components/Driver";
import { Readout } from "../components/Readout";
import { Straight } from "../instrument/Straight";
import { loadStraightProfile } from "../instrument/load";
import { useList, useLoad } from "../lib/api";
import { fixed, int } from "../lib/format";
import { href } from "../lib/router";
import type { Driver, SessionRow } from "../lib/types";
import { usePage } from "../motion";
import { Forest, MakerRows, NB, PermutationChart } from "../findings/charts";
import { QUOTES } from "../findings/quotes";
import "../findings/findings.css";

const REPO = "https://github.com/DrissiAli221/f1-battery/blob/main/";

// The opening instrument: Monza race, NOR, the straight the landing uses (D30 profile).
const PROFILE = { session: 11361, circuit: 39, straight: 2, driver: 1 } as const;
const STRAIGHT_NAME = (straightNames as Record<string, Record<string, string>>)["39"]?.[String(PROFILE.straight)] ?? "Straight 2";

function fmtFrozen(iso: string) {
  return new Date(`${iso}T00:00:00Z`).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
}

function Head({ title, children, id }: { title: string; children?: React.ReactNode; id: string }) {
  return (
    <div className="fx-head">
      <h2 id={id} className="fx-h2" data-reveal>
        {title}
      </h2>
      {children && (
        <p className="fx-head__text" data-reveal>
          {children}
        </p>
      )}
    </div>
  );
}

function useQuoteDrivers(): Map<string, Driver> {
  const sessions = useList<SessionRow>("/sessions");
  // The latest race with results: its driver list carries the current headshots and team colours.
  const latest = sessions.data?.find((s) => s.session_name === "Race" && s.has_results) ?? null;
  const drivers = useList<Driver>(latest ? `/sessions/${latest.session_key}/drivers` : null);
  const out = new Map<string, Driver>();
  for (const d of drivers.data ?? []) if (d.name_acronym) out.set(d.name_acronym, d);
  return out;
}

export function FindingsPage() {
  const profile = useLoad(`fx-profile:${PROFILE.session}:${PROFILE.straight}:${PROFILE.driver}`, () =>
    loadStraightProfile(PROFILE.session, PROFILE.circuit, PROFILE.straight, PROFILE.driver),
  );
  const drivers = useQuoteDrivers();
  const root = usePage<HTMLDivElement>(undefined, [drivers.size, profile.data]);

  const s = findings.sample;
  const runs = findings.runs;
  const perm = findings.permutation;
  const lr = findings.energy_terms_lr;
  const termName = notes.terms as Record<string, string>;
  const frozen = fmtFrozen(notes.frozen);
  const p = (v: number) => (v < 0.001 ? `p${NB}<${NB}0.001` : `p${NB}=${NB}${fixed(v, 3)}`);
  // The cut-off term is reported in the frozen direction (earlier cut-off) in the runs block; the
  // full model keeps the fitted direction (later cut-off), so it is labelled as such.
  const terms = findings.terms.map((t) => ({
    label: termName[t.term] ?? t.term,
    sub: `${t.unit}${t.term === "cutoff_dev_defender" ? ", later cut-off" : ""} · ${p(t.p)}`,
    or: t.or,
    lo: t.lo,
    hi: t.hi,
    strong: t.p < 0.05,
  }));

  const caption = profile.data
    ? null
    : profile.loading
      ? "Loading the speed profile."
      : "The speed profile for this straight is not published yet; the axis is drawn without its trace.";

  return (
    <div ref={root}>

      <section className="wrap fx-open" aria-labelledby="fx-q">
        <div data-intro>
          <Straight
            profile={profile.data}
            pending={profile.loading}
            size="panel"
            d={{ mode: "pointer" }}
            labels={{ circuit: "Monza race", straight: STRAIGHT_NAME, driver: "NOR" }}
          />
          {caption && <p className="fx-open__caption">{caption}</p>}
        </div>

        <div className="fx-stamp-row" data-intro data-delay="0.1">
          <p className="fx-stamp">No effect</p>
          <p className="fx-stamp-date">
            pre-registered {frozen}
            <span>model {findings.source.model_version}, run {findings.source.run_id.slice(0, 8)}</span>
          </p>
        </div>

        <Readout label="Verdict">
          No effect · OR {fixed(runs.point.or, 2)} ({fixed(runs.point.lo, 2)}–{fixed(runs.point.hi, 2)})
        </Readout>
        <h1 id="fx-q" className="fx-h1" data-intro data-delay="0.15">
          {notes.question}
        </h1>

        <div className="fx-answer" data-intro data-delay="0.2">
          <div>
            <p className="fx-answer__lead">{notes.verdict_sentence}</p>
            <p className="fx-answer__caveat">{notes.caveat}</p>
          </div>
        </div>

        <dl className="fx-sample" data-reveal>
          {(
            [
              ["Passes extracted", s.events_extracted],
              ["Passes tested", s.events_tested],
              ["Close-following non-passes tested", s.non_events_tested],
              ["Sessions in the model", s.sessions_in_model],
            ] as const
          ).map(([l, v]) => (
            <div key={l}>
              <dt>{l}</dt>
              <dd>{int(v)}</dd>
            </div>
          ))}
        </dl>
      </section>

      <section className="wrap fx-section" aria-labelledby="fx-belief">
        <Head id="fx-belief" title="The paddock already believes it">
          Drivers say the battery decides fights. Nobody had counted it across a season. {notes.hidden_fact}
        </Head>
        <div className="fx-quotes">
          {QUOTES.map((q) => {
            const d = drivers.get(q.code);
            return (
              <figure key={q.code} className="fx-quote" data-reveal>
                <div>
                  <blockquote>“{q.text}”</blockquote>
                  <figcaption>
                    <Avatar
                      size={52}
                      d={
                        d ?? {
                          driver_number: 0,
                          name_acronym: q.code,
                          team_colour: null,
                          headshot_url: null,
                          team_name: q.team,
                        }
                      }
                    />
                    <p className="fx-quote__who">
                      {q.name} <span className="fx-quote__code">{q.code}</span>
                      <span>
                        {d?.team_name ?? q.team} · {q.source}
                      </span>
                    </p>
                  </figcaption>
                </div>
              </figure>
            );
          })}
        </div>
      </section>

      <section className="wrap fx-section" aria-labelledby="fx-runs">
        <Head id="fx-runs" title="Three runs, none near the bar">
          Logistic regression of being passed on the defender’s cut-off deviation on the approach straight, with pace, tyre age, lap,
          Overtake availability and a session effect. The median cut-off is known only to its bootstrap interval, so the test runs at
          the point estimate and at both interval edges. Odds ratio per 1{NB}SD earlier cut-off; the frozen bar was 1.3.
        </Head>
        <Forest
          domain={[0.6, 1.6]}
          ticks={[0.6, 0.7, 0.8, 0.9, 1, 1.2, 1.4, 1.6]}
          bar={1.3}
          caption="Odds ratios with 95 % intervals for the three runs; all three sit below 1 and far from the pre-registered bar of 1.3."
          rows={[
            { label: "Point estimate", sub: "deviation from the median", ...runs.point, strong: true },
            { label: "Lower interval edge", sub: "deviation from ci_high", ...runs.lower_edge },
            { label: "Upper interval edge", sub: "deviation from ci_low", ...runs.upper_edge },
          ]}
        />
        <p className="fx-note" data-reveal>
          All three sit below 1: an earlier cut-off goes with slightly lower odds of being passed, the opposite of the hypothesis, and
          two of the three intervals include 1. The energy terms together add nothing detectable beyond the controls (likelihood ratio
          χ² <span className="fx-mono">{fixed(lr.chi2, 2)}</span>, <span className="fx-mono">{lr.df}</span>
          {NB}df, <span className="fx-mono">p{NB}={NB}{fixed(lr.p, 2)}</span>).
        </p>
      </section>

      <section className="wrap fx-section" aria-labelledby="fx-pace">
        <Head id="fx-pace" title="Pace, not energy">
          The full model at the point estimate. Terms with p below 0.05 are drawn in ink, the rest muted. An odds ratio below 1 for pace
          delta means a faster attacker makes a pass more likely.
        </Head>
        <Forest
          domain={[0.5, 3.5]}
          ticks={[0.5, 0.75, 1, 1.5, 2, 3]}
          caption="Odds ratios with 95 % intervals for every term of the full model. Pace delta, tyre age, lap number and Overtake availability have p below 0.05; the three energy terms do not."
          rows={terms}
        />
      </section>

      <section className="wrap fx-section" aria-labelledby="fx-perm">
        <Head id="fx-perm" title="Indistinguishable from shuffled data">
          The three energy variables were shuffled within each session {int(perm.n)} times and the model refitted. The observed
          coefficient is more extreme than only <span className="fx-mono">{fixed(perm.pct_abs, 1)}{NB}%</span> of the shuffled ones;
          the frozen requirement was more than 95{NB}%. Two-sided <span className="fx-mono">p{NB}={NB}{fixed(perm.p_two_sided, 2)}</span>.
        </Head>
        <PermutationChart h={perm.histogram} observed={perm.observed} q95={perm.q95_abs} n={perm.n} />
      </section>

      <section className="wrap fx-section" aria-labelledby="fx-checks">
        <Head id="fx-checks" title="Five spot checks, fixed in advance">
          Written before any model output existed (docs/spot-checks.md). Three fail, one passes, one cannot be tested. Expected signs were
          not changed after the fact.
        </Head>
        <ol className="fx-checks">
          {notes.spot_checks.map((c) => (
            <li key={c.n} data-reveal>
              <span className="fx-checks__n">{String(c.n).padStart(2, "0")}</span>
              <p className="fx-checks__moment">{c.moment}</p>
              <p className="fx-checks__detail">{c.detail}</p>
              <p className={`fx-checks__result ${c.result === "pass" ? "is-pass" : c.result === "fail" ? "is-fail" : "is-not"}`}>
                {c.result}
              </p>
            </li>
          ))}
        </ol>
      </section>

      <section className="wrap fx-section" aria-labelledby="fx-makers">
        <Head id="fx-makers" title="Where each maker cuts">
          Not part of the frozen test. Per race session and straight, each maker’s median cut-off against the mean of all makers. The
          tick is the average offset, the band ±1{NB}sd across cells. Cut-off position also depends on drag and mass assumptions that
          cannot be separated here, so a difference is not a difference in energy capacity.
        </Head>
        <MakerRows makers={findings.makers} />
      </section>

      <section className="wrap fx-section" aria-labelledby="fx-limits">
        <Head id="fx-limits" title="What this cannot say" />
        <dl className="fx-limits">
          {notes.limits.map(([t, d]) => (
            <div key={t} data-reveal>
              <dt>{t}</dt>
              <dd>{d}</dd>
            </div>
          ))}
        </dl>
        <p className="fx-note" data-reveal>
          Numbers on this page come from the output of{" "}
          <a className="link" href={REPO + findings.source.script} target="_blank" rel="noreferrer">
            {findings.source.script}
          </a>{" "}
          for run <span className="fx-mono">{findings.source.run_id.slice(0, 8)}</span>. Full write-up:{" "}
          <a className="link" href={REPO + "docs/findings.md"} target="_blank" rel="noreferrer">
            docs/findings.md
          </a>
          . How the method got here: the{" "}
          <a className="link" href={href.method}>
            method log
          </a>
          .
        </p>
      </section>
    </div>
  );
}
